style.css:
/* ১. পুরো পেজের সব লেখার রঙ উজ্জ্বল সবুজ (Green) করার জন্য */
body, body *, div, span, p, a, h1, h2, h3, h4, button, input {
    color: #00FF00 !important; /* উজ্জ্বল সবুজ রঙ (HEX Code) */
    text-shadow: 0 0 2px #003300; /* স্পষ্ট দেখার জন্য হালকা ব্যাকগ্রাউন্ড শ্যাডো */
}

/* ২. পুরো পেজে নিজের মতো টাইপ বা এডিট করার পারমিশন চালুর জন্য */
html {
    -webkit-user-modify: read-write-plaintext-only !important;
}
